def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the number string `num_str`.
    The string is assumed to consist of decimal digits only. If K is negative or greater than N-1, or if the
    string contains non-digit characters, the function returns 0.
    """
    # Validate input
    if not num_str or not num_str.isdigit():
        return 0
    N = len(num_str)  # ensure consistency
    if K < 0 or K > N - 1:
        return 0
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Precompute integer values of all substrings to avoid repeated conversions
    # substr_val[i][j] will hold int(num_str[i:j]) for 0 <= i < j <= N
    substr_val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            substr_val[i][j] = val

    # DP table: dp[i][k] = max product for prefix of length i with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    # Base case: no multiplication
    for i in range(1, N + 1):
        dp[i][0] = substr_val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        # At least k+1 digits needed to place k multiplications
        for i in range(k + 1, N + 1):
            max_prod = 0
            # j is the split point: previous part ends at j, current part starts at j
            # j must be at least k because we need k-1 splits in the prefix of length j
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev == 0:
                    continue
                cur = substr_val[j][i]
                prod = prev * cur
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K] if dp[N][K] != 0 else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        ValueError: If inputs are invalid (e.g., n negative, coeffs length mismatch).
    """
    # Basic validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(coeffs, list):
        raise ValueError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")
    for c in coeffs:
        if not isinstance(c, int):
            raise ValueError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'

    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    # Basic validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        return "NO ANSWER!"
    if A == B:
        return 0
    if not rules:
        return "NO ANSWER!"

    from collections import deque

    max_depth = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, steps = queue.popleft()
        if steps >= max_depth:
            continue
        next_steps = steps + 1
        for src, tgt in rules:
            if not isinstance(src, str) or not isinstance(tgt, str) or not src:
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_steps
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_steps))
                start = idx + 1  # allow overlapping replacements
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re

    # Basic input validation
    try:
        if not isinstance(scenario, str):
            return False
        if not isinstance(liar_count, set):
            return False
        if not isinstance(statements, dict):
            return False
        if not isinstance(days_of_week, set):
            return False
    except Exception:
        return False

    # Precompile regex patterns for guilt statements
    guilt_pattern = re.compile(r'(?P<subject>\w+)\s+is\s+(not\s+)?guilty', re.IGNORECASE)
    i_pattern = re.compile(r'I\s+am\s+(not\s+)?guilty', re.IGNORECASE)

    # Normalize days of week for case-insensitive comparison
    days_lower = {day.lower() for day in days_of_week}

    for speaker, stmts in statements.items():
        if not isinstance(stmts, list):
            return False
        for stmt in stmts:
            if not isinstance(stmt, str):
                return False
            stmt_lower = stmt.lower()
            # Skip statements that mention a day of the week
            if any(day in stmt_lower for day in days_lower):
                continue

            # Determine if the statement is about guilt
            match = i_pattern.match(stmt_lower)
            if match:
                subject = speaker
                not_guilty = bool(match.group('not'))
            else:
                match = guilt_pattern.search(stmt_lower)
                if match:
                    subject = match.group('subject').upper()
                    not_guilty = bool(match.group('not'))
                else:
                    # Not a guilt statement; ignore
                    continue

            # Evaluate truth of the statement
            if not_guilty:
                truth = (subject != scenario)
            else:
                truth = (subject == scenario)

            # Check consistency with liar status
            if speaker in liar_count:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement

    return True

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Compute Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If student_scores is not a list.
        ValueError: If any element is not a tuple of length 3 or contains non‑numeric values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError(f"Element {idx} is not a tuple of length 3")
        student_number, total_score, chinese_score = item
        if not isinstance(student_number, int):
            raise ValueError(f"Student number at index {idx} must be an integer")
        if not isinstance(total_score, (int, float)):
            raise ValueError(f"Total score at index {idx} must be numeric")
        if not isinstance(chinese_score, (int, float)):
            raise ValueError(f"Chinese score at index {idx} must be numeric")

    # Sort by total_score descending, then Chinese_score descending, then student_number ascending
    return sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
